/* Low-typing setup and journalled schedule transitions. Stored prose and roster rules are preserved. */
(()=>{'use strict';
const A=()=>window.MMCampaignAutomation,S=()=>window.MMCampaignSchedule,E=s=>esc(String(s??'')),T=(en,ko)=>window.UKI18n?.language==='en'?en:ko,L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(T(en,ko))}</span>`,copy=x=>structuredClone(x),account=()=>window.AccountParity?.account?.id||'',labelName=(en,ko)=>T(en,ko);
const canEdit=c=>!!A()?.canEdit(c),canJoin=c=>canEdit(c)&&(!c.remoteRole||c.remoteRole==='owner')&&(!c.remoteOwnerId||c.remoteOwnerId===account());
function uniqueName(base,records){const taken=new Set((records||[]).map(x=>String(x.name||'').trim().toLowerCase()));for(let n=1;n<100000;n++){const name=base+' '+String(n).padStart(3,'0');if(!taken.has(name.toLowerCase()))return name;}return base+' '+Date.now();}
function failure(error){A()?.notify(error.message||String(error),true);return false;}
function modal(en,ko,fields,submit,fn){cpModal(T(en,ko),fields,submit,values=>Promise.resolve().then(()=>fn(values)).catch(error=>{cpMessage(error.message||String(error));return false;}));window.UKI18n?.refresh();}
function operationNumber(c,prefix){return (A()?.receipts(c)||[]).filter(r=>(r.operationKey||r.key||'').startsWith(prefix)).length+1;}
function pending(c,atCycle){return {battles:(c.battles||[]).filter(b=>Number(b.cycle)===atCycle&&b.challenge&&b.status!=='Played'),sessions:(c.sessions||[]).filter(s=>s.status!=='Completed'&&(!s.cycle||Number(s.cycle)===atCycle)),challenges:window.MMCampaignChallenges?.pending(c)||[]};}
async function advance(c,carry=false){const s=S()?.info(c);if(!canEdit(c)||!s||s.complete||s.outOfRange)return false;const p=pending(c,s.cycle);if(!carry&&(p.battles.length||p.sessions.length||p.challenges.length)){modal('Unfinished cycle records','미완료 사이클 기록',`<p class="wide">${L('Unresolved challenges','미해결 도전')}: ${p.battles.length+p.challenges.length} · ${L('Open sessions','진행 중인 전투')}: ${p.sessions.length}</p><label class="checkline wide"><input type="checkbox" name="carry" value="yes">${L('Keep these unresolved records and explicitly carry them forward.','미완료 기록을 유지한 채 다음 사이클로 보류합니다.')}</label>`,T('Carry forward and advance','보류하고 다음 사이클'),v=>{if(v.carry!=='yes')throw Error(T('Confirm carry-over or resolve the records first.','보류를 확인하거나 먼저 기록을 처리하세요.'));if(S().info(c)?.cycle!==s.cycle)throw Error('Cycle changed');return advance(c,true);});return false;}
 const prefix=`cycle-advance:${s.cycle}:`,key=prefix+operationNumber(c,prefix),signature=JSON.stringify(c.campaignSchedule),end=s.cycle===s.total;
 const closing=window.MMCampaignEconomy?.supported(c)?MMCampaignEconomy.participants(c).filter(g=>MMCampaignEconomy.tradingStepNeedsClose(c,g)):[];return A().apply(c,{key,label:T('Advance campaign cycle','캠페인 다음 사이클'),gangIds:closing.map(g=>g.id),mutate:draft=>{const dc=draft.campaign;if(!canEdit(c)||JSON.stringify(dc.campaignSchedule)!==signature||Number(dc.currentCycle||1)!==s.cycle)throw Error('Campaign schedule changed');for(const g of draft.gangs.filter(g=>closing.some(x=>x.id===g.id)))MMCampaignEconomy.expireTradePoints(dc,g);const plan=dc.campaignSchedule;plan.history??=[];plan.history.push({id:id(),at:now(),fromCycle:s.cycle,toCycle:end?s.cycle:s.cycle+1,finishedBefore:s.complete,finishedAfter:end,automationOperationKey:key,carriedUnresolved:carry});dc.currentCycle=end?s.cycle:s.cycle+1;plan.completed=end;(dc.activity??=[]).push({id:id(),at:now(),text:end?'Campaign schedule completed':`Campaign advanced to cycle ${dc.currentCycle}`});}});
}
async function undo(c){const s=S()?.info(c),h=s?.plan.history?.filter(h=>!h.undoneAt).at(-1);if(!canEdit(c)||!h||h.toCycle!==s.cycle||h.finishedAfter!==s.complete)return false;if(h.automationOperationKey){let r=A().receipt(c,h.automationOperationKey);if(!r){await A().loadReceipts(c);r=A().receipt(c,h.automationOperationKey);}if(!r)throw Error(T('Load the operation history before reversing this step.','진행 이력을 불러온 뒤 이번 사이클 진행을 취소하세요.'));return A().reverse(c,r.id);}
 return A().apply(c,{key:`cycle-legacy-undo:${h.id}`,label:T('Reverse legacy schedule step','기존 사이클 진행 되돌리기'),gangIds:[],mutate:draft=>{const dc=draft.campaign,last=dc.campaignSchedule.history.filter(x=>!x.undoneAt).at(-1);if(!last||last.id!==h.id||dc.currentCycle!==h.toCycle)throw Error('The latest schedule step changed');dc.currentCycle=h.fromCycle;dc.campaignSchedule.completed=h.finishedBefore;last.undoneAt=now();}});
}
function configure(c){if(!canEdit(c))return false;const signature=JSON.stringify(c.campaignSchedule),current=Number(c.currentCycle||1),type=c.campaignTypeId||'manual';modal('Campaign progression','캠페인 진행 방식',S().fields(c.edition,type,c)+`<p class="wide">${L('Current cycle','현재 사이클')}: ${current}. ${L('Existing battles, rosters and rewards are retained.','기존 전투·로스터·보상은 유지합니다.')}</p>`,T('Save Changes','변경 사항 저장'),()=>{const next=S().read(document.querySelector('#modal-form'),c.edition,type);if(next.error)throw Error(next.error);if(next.value.stages.reduce((n,s)=>n+s.cycles,0)<current)throw Error(T('Include the current recorded cycle in the plan.','계획에 현재 기록된 사이클을 포함하세요.'));const prefix='schedule-configure:';return A().apply(c,{key:prefix+operationNumber(c,prefix),label:T('Configure campaign progression','캠페인 진행 설정'),gangIds:[],mutate:draft=>{if(JSON.stringify(draft.campaign.campaignSchedule)!==signature)throw Error('Campaign schedule changed');draft.campaign.campaignSchedule={...next.value,history:draft.campaign.campaignSchedule?.history||[],completed:!!draft.campaign.campaignSchedule?.completed&&current===next.value.stages.reduce((n,s)=>n+s.cycles,0)};draft.campaign.currentCycle=current;}});});S().bind(document.querySelector('#modal-form'),()=>({edition:c.edition,typeId:type}));return true;}
function fillCreation(form){if(!form?.elements.campaignType)return;const name=form.elements.name;if(name&&!name.value.trim()){name.value=uniqueName(T('Campaign','캠페인'),data.campaigns);name.dispatchEvent(new Event('input',{bubbles:true}));}const edition=form.elements.edition?.value,source=(window.RULES_DATA?.campaignTypes||[]).find(r=>r.source_verified&&String(r.edition_slug||r.edition).toUpperCase()===edition&&r.id==='official-003-campaign-necromunda-campaign');if(source&&!form.elements.campaignType.value){if(typeof cpSetFieldValue==='function')cpSetFieldValue(form.elements.campaignType,source.id);else{form.elements.campaignType.value=source.id;form.elements.campaignType.dispatchEvent(new Event('change',{bubbles:true}));}}}
function foldOptional(form,existing=false){if(form.querySelector('.cq-extra-settings'))return;const details=document.createElement('details');details.className='cq-extra-settings wide';details.innerHTML=`<summary>${L('More settings & written notes','추가 설정·작성한 설명')}</summary>`;for(const n of [...form.children])if(existing&&n.matches('fieldset')||n.querySelector('textarea,[name^="resource_"],[name^="allegiance_"],#cp-resource-name,#cp-allegiance-name,[name="allegiance"]'))details.append(n);if(details.children.length>1)form.append(details);}
const priorEdit=editCampaign;editCampaign=function(c){if(c&&(!data.campaigns.includes(c)||!window.MMCampaignSessionData?.canEdit(c)))return false;const result=priorEdit.apply(this,arguments),form=document.querySelector('#modal-form');if(!form)return result;if(form.dataset.officialManual){if(!c&&form.elements.name&&!form.elements.name.value){form.elements.name.value=uniqueName(T('Campaign','캠페인'),data.campaigns);form.elements.name.dispatchEvent(new Event('input',{bubbles:true}));}foldOptional(form,!!c);return result;}if(!c){if(form.elements.edition&&form.elements.edition.value!=='N26'&&(window.RULES_DATA?.campaignTypes||[]).some(r=>r.source_verified&&r.id==='official-003-campaign-necromunda-campaign')){form.elements.edition.value='N26';form.elements.edition.dispatchEvent(new Event('change',{bubbles:true}));}fillCreation(form);foldOptional(form);form.addEventListener('change',e=>{if(e.target.name==='edition')fillCreation(form);});}else foldOptional(form,true);return result;};
function joinOptions(c){return data.gangs.filter(g=>String(g.edition).toUpperCase()===String(c.edition).toUpperCase()&&!g.remoteReadOnly&&(!g.remoteOwnerId||g.remoteOwnerId===account())&&!c.members?.some(m=>m.gangId===g.id));}
newMember=function(){const c=campaign();if(!canJoin(c))return false;const owner=account(),options=joinOptions(c);modal('Add your gang','내 갱 참가',`<label class="wide">${L('Gang','갱')}<select name="gangId">${options.map(g=>`<option value="${E(g.id)}" data-user-text>${E(g.name)}</option>`).join('')}</select></label><p class="wide">${L('Player','플레이어')}: <strong data-user-text>${E(window.AccountParity?.account?.username||cpPlayerName())}</strong></p>${c.allegiances?.length?`<label class="wide">${L('Allegiance','진영')}<select name="allegiance"><option value="">—</option>${c.allegiances.map(a=>`<option value="${E(a.id)}" data-user-text>${E(a.name)}</option>`).join('')}</select></label>`:''}<p class="wide">${L('Other players join through campaign invitations or online enrollment.','다른 플레이어는 초대 또는 온라인 참가로 등록합니다.')}</p>`,T('Add Gang','갱 참가'),v=>{if(owner!==account()||!canJoin(c))throw Error('Account or permissions changed');const g=joinOptions(c).find(g=>g.id===v.gangId),allegiance=v.allegiance||'';if(!g||allegiance&&!c.allegiances.some(a=>a.id===allegiance))throw Error(T('Choose an available gang.','참가 가능한 갱을 고르세요.'));const player=window.AccountParity?.account?.username||cpPlayerName();return A().apply(c,{key:`manual-join:${window.MMCampaignEconomy?.compactKeys([g.id])||g.id}`,label:T('Gang joins campaign','갱 캠페인 참가'),gangIds:[],mutate:draft=>{if(draft.campaign.members.some(m=>m.gangId===g.id))throw Error('Gang already joined');draft.campaign.members.push({id:id(),gangId:g.id,player,role:'Player',allegianceId:allegiance});}});});if(!options.length)document.querySelector('#modal-submit').disabled=true;return true;};
function skWrite(){const a=window.AccountParity;return !(a&&(a.connecting||a.busy||a.account&&!a.ready));}
function currentSkirmish(){return data.view==='dashboard'&&data.homeTab==='skirmishes'?(data.skirmishes||[]).find(s=>s.id===data.selectedSkirmish&&s.stage==='setup'):null;}
function skirmishPreview(s){if(!skWrite()||s!==currentSkirmish())throw Error('Skirmish changed');const tables={};for(const key of ['deploymentId','objectiveId','crewId'])if(!s[key]){const r=window.MMSkirmish?.rollTable(key);if(!r)throw Error('Verified scenario table unavailable');tables[key]={id:r.row.id,name:r.row.name,roll:r.value};}let roleRoll=null;if(!s.roleRoll||s.roleRoll.winner<0){const dice=[MMSkirmish.die(6),MMSkirmish.die(6)];roleRoll={dice,winner:dice[0]===dice[1]?-1:dice[0]>dice[1]?0:1};}return {tables,roleRoll};}
function prepareSkirmish(){const s=currentSkirmish();if(!s||!skWrite())return;const owner=account(),before=JSON.stringify(s),p=skirmishPreview(s);if(!Object.keys(p.tables).length&&!p.roleRoll)return false;showModal(L('Prepare undecided skirmish steps','스커미시 준비'),`<p>${L('Roll only undecided mission tables and the role roll-off. The roll-off winner still chooses the attacker. Crews, tactics and physical setup remain explicit choices.','미정인 미션 표와 역할 롤오프만 굴립니다. 롤오프 승자가 공격자를 직접 선택하며, 크루·택틱·실제 전장 준비도 직접 확인합니다.')}</p><ul>${Object.entries(p.tables).map(([k,r])=>`<li>D6 ${r.roll} · ${E(r.name)}</li>`).join('')}</ul>${p.roleRoll?`<p>A ${p.roleRoll.dice[0]} · B ${p.roleRoll.dice[1]} · ${p.roleRoll.winner<0?L('Tie · roll again','동률·다시 굴림'):L('Winner chooses attacker','승자가 공격자 선택')}</p>`:''}`,T('Apply preparation','준비 완료'),()=>{if(owner!==account()||s!==currentSkirmish()||!skWrite()||JSON.stringify(s)!==before)return false;for(const [key,r]of Object.entries(p.tables)){s[key]=r.id;s.tableRolls??={};s.tableRolls[key]=r.roll;}if(p.roleRoll)s.roleRoll=copy(p.roleRoll);save();return true;});window.UKI18n?.refresh();}
function skirmishForm(form){if(!form?.elements.gang0||form.dataset.cqPrepared)return;form.dataset.cqPrepared='true';const choices=data.gangs.filter(g=>g.edition==='N26'),a=form.elements.gang0,b=form.elements.gang1;if(!a.value&&choices[0])a.value=choices[0].id;if(!b.value){const next=choices.find(g=>g.id!==a.value);if(next)b.value=next.id;}
 function sync(){for(const i of [0,1]){const g=choices.find(g=>g.id===form.elements['gang'+i].value),input=form.elements['name'+i],label=input?.closest('label');if(label)label.hidden=!!g;if(g&&input){input.value=g.name;input.dataset.cqAutoName=g.name;}else if(input&&input.value===input.dataset.cqAutoName)input.value='';}const title=form.elements.title;if(title&&(!title.value||title.value===title.dataset.cqAutoTitle)){const names=[a.value,b.value].map(id=>choices.find(g=>g.id===id)?.name).filter(Boolean);title.value=names.length===2?names.join(' vs '):uniqueName(T('Skirmish','스커미시'),data.skirmishes);title.dataset.cqAutoTitle=title.value;}}
 sync();form.addEventListener('change',sync);
}
function refresh(){skirmishForm(document.querySelector('#modal-form'));const s=currentSkirmish(),host=document.querySelector('.sk-page');if(!s||s.stage!=='setup'||!host||host.querySelector('[data-cq-prepare]'))return;const b=document.createElement('button');b.type='button';b.className='btn';b.dataset.cqPrepare='';b.innerHTML=L('Prepare undecided steps','남은 준비 주사위 굴리기');b.disabled=!skWrite()||!!s.deploymentId&&!!s.objectiveId&&!!s.crewId&&s.roleRoll?.winner>=0;const heading=host.querySelector('.sk-heading'),preparation=host.querySelector('[data-bp-panel=round]');if(heading)heading.append(b);else if(preparation)preparation.prepend(b);else host.prepend(b);window.UKI18n?.refresh(b);}
document.addEventListener('click',e=>{if(e.target.closest('[data-cq-prepare]')){e.preventDefault();try{prepareSkirmish();}catch(error){failure(error);}}});
const previous=render;render=function(){const result=previous.apply(this,arguments);refresh();return result;};let queued=false;new MutationObserver(()=>{if(!queued){queued=true;queueMicrotask(()=>{queued=false;refresh();});}}).observe(document.body,{childList:true,subtree:true});refresh();
window.MMCampaignQuickFlow={advance,undo,configure,uniqueName,fillCreation,joinOptions,canJoin,pending,skirmishPreview,prepareSkirmish,refresh};
})();
